
// ---------- CP-72 add-on (Jenny, Nov 18): Zoomies sound as a Developer choice ----------
// "Pusher sound: replace the turbo rev with the sound of coins being pushed; 2-3 real candidates as a Developer choice next
// to today's, I pick on my phone." Settings -> Developer -> Engineer tools -> "Zoomies sound": Today (the turbo rev, default)
// / P1 / P2 / P3, saved on this phone (localStorage catpusher.uat.cp72zsound.v1). Only Zoomies' turbo rev (sfx.wild('turbo')
// inside z72Start) is swapped; the round's own Turbo keeps its rev. P1-P3: real CC0 recordings (Freesound 776505 coins on wood,
// 563265 coin push on table, 485770 coins slid off a table; work/cp72-pusher-sound/make.py), 7 s beds cleaned and levelled,
// played on the effects master at CP72Z.gain x the wild() volume (3 dB under today's burst), and stopped (0.15 s fade) as soon
// as Zoomies ends, or on mute / background. Not decoded yet: today's rev, so Zoomies is never silent.
const CP72Z=(()=>{const B64={P1:"",P2:"",P3:""};
 const KEY='catpusher.uat.cp72zsound.v1',CHOICES=['today','P1','P2','P3'],NAMES={today:'Today',P1:'P1',P2:'P2',P3:'P3'};
 let pick='today';try{const v=localStorage.getItem(KEY);if(CHOICES.includes(v))pick=v;}catch(e){}
 const bufs={},asked={},stats={played:{},stopped:0};let h=null,inZ=false;
 function load(k){if(asked[k]||!B64[k])return;asked[k]=true;try{const b=atob(B64[k]),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);
  if(!sfx._dec(u.buffer,x=>{bufs[k]=x;}))asked[k]=false;else setTimeout(()=>{if(!bufs[k])asked[k]=false;},2000);}catch(e){asked[k]=false;}}
 function set(k){if(!CHOICES.includes(k))return;pick=k;try{localStorage.setItem(KEY,k);}catch(e){}load(k);}
 function get(){return pick;}
 function warm(){if(pick!=='today'&&!bufs[pick])load(pick);}
 function play(k,vol){stop();const v=vol*(typeof pickupFx==='object'?pickupFx.volume:1)*CP72Z.gain;h=sfx._playBufH(bufs[k],v);if(h){stats.played[k]=(stats.played[k]||0)+1;return true;}return false;}
 function stop(f){if(h){h.stop(f);h=null;stats.stopped++;}}
 return {B64,KEY,CHOICES,NAMES,gain:0.11,bufs,asked,load,set,get,warm,play,stop,stats,get playing(){return !!h;},get inZ(){return inZ;},set inZ(v){inZ=v;}};})();
const __cp72zWild=sfx.wild;
sfx.wild=function(kind,vol=1,...a){
 if(kind==='turbo'&&CP72Z.inZ&&CP72Z.get()!=='today'){const k=CP72Z.get();CP72Z.load(k);if(CP72Z.bufs[k]&&CP72Z.play(k,vol))return;}
 return __cp72zWild.call(this,kind,vol,...a);};
const __cp72zStart=z72Start;
z72Start=function(){CP72Z.inZ=true;try{return __cp72zStart.apply(this,arguments);}finally{CP72Z.inZ=false;}};
// each frame: decode the chosen sound early; stop it the moment Zoomies is over (or sound is off / the app is in the background)
const __cp72zUpdate=update;update=function(dt){__cp72zUpdate(dt);try{CP72Z.warm();if(CP72Z.playing&&(!Z72X||S.muted||inBackground||document.hidden))CP72Z.stop(.15);}catch(e){}};
// the choice in Engineer tools, under the Yawn sound; tapping one plays 2 s of it
const __cp72zCredits=openCredits;
openCredits=function(){const r=__cp72zCredits.apply(this,arguments);try{
 const eng=panel.querySelector&&panel.querySelector('#cp70-engineer');if(!S.dev||!eng||eng.querySelector('#cp72-zsound'))return r;
 const box=document.createElement('div');box.id='cp72-zsound';const hd=document.createElement('h3');hd.textContent='Zoomies sound';box.appendChild(hd);
 const btns=[];const paint=()=>btns.forEach(b=>{const on=b.dataset.zs===CP72Z.get();b.textContent=(on?'✓ ':'')+CP72Z.NAMES[b.dataset.zs];b.style.fontWeight=on?'700':'400';});
 for(const k of CP72Z.CHOICES){const b=document.createElement('button');b.dataset.zs=k;b.style.marginRight='6px';
  b.onclick=()=>{CP72Z.set(k);paint();setTimeout(()=>{try{if(k==='today')sfx.wild('turbo',1);else if(CP72Z.bufs[k]&&CP72Z.play(k,1))setTimeout(()=>CP72Z.stop(.3),2000);}catch(e){}},k==='today'||CP72Z.bufs[k]?0:300);};btns.push(b);box.appendChild(b);}
 paint();const after=eng.querySelector('#cp79-yawn');if(after&&after.nextSibling)eng.insertBefore(box,after.nextSibling);else{const sum=eng.querySelector('summary');if(sum&&sum.nextSibling)eng.insertBefore(box,sum.nextSibling);else eng.appendChild(box);}}catch(e){}return r;};
